Dear All:
I am using the R function optim to run some simulations. I get thrown out
of the simulations and here is the error message that is generated :"Error
in optim(ss, bblik, bblik.g, method = "L-BFGS-B", lower = rep(0,  : 
        L-BFGS-B needs finite values of fn"

Is there anyway around this. I truly appreciate any help I can get.

If needed, here are the simulation ,objective, and the gradient functions
that I am running.
###############################################################
m9r.2d5<-function(param,ds,dams){
rho<-param[4:length(param)]
phi<-rho/(1-rho)
param<-c(param[1:3],phi)
dd<-rep(ds[1:length(ds)],dams)
dd<-sort(dd)
dose <- sort(unique(dd))
mu <- 1 - exp(-param[1]-param[2]*dd-param[3]*dd^2)
counts <- rep(0,length(dose))
for(i in 1:length(dose)){
counts[i] <- sum(dd==dose[i])
}
phi <- rep(param[4:length(param)],counts)
ss<-round(param,digits=3)
nsimul<-4
while(nsimul<=2000)
{
alp<-mu/phi
gam<-(1-mu)/phi
y<-rep(0,length(dd))
ps<-rep(0,length(dd))
nn<-rep(0,length(dd))
uu<-rep(0,length(dd))
for(i in 1:length(dd)){
ps[i]<-rbeta(1,alp[i],gam[i])
uu[i]<-runif(1)
if(uu[i]<=3/555) nn[i]<-1
if((uu[i]>3/555) &(uu[i]<=5/555))nn[i]<-2
if((uu[i]>5/555) & (uu[i]<=9/555))nn[i]<-3
if((uu[i]>9/555) &(uu[i]<=10/555))nn[i]<-4
if((uu[i]>10/555) &(uu[i]<=12/555))nn[i]<-5
if((uu[i]>12/555) &(uu[i]<=17/555))nn[i]<-6
if((uu[i]>17/555) &(uu[i]<=30/555))nn[i]<-7
if((uu[i]>30/555) &(uu[i]<=51/555))nn[i]<-8
if((uu[i]>51/555) &(uu[i]<=115/555))nn[i]<-9
if((uu[i]>115/555) &(uu[i]<=210/555))nn[i]<-10
if((uu[i]>210/555) &(uu[i]<=352/555))nn[i]<-11
if((uu[i]>352/555) &(uu[i]<=444/555))nn[i]<-12
if((uu[i]>444/555) &(uu[i]<=497/555))nn[i]<-13
if((uu[i]>497/555) &(uu[i]<=526/555))nn[i]<-14
if((uu[i]>526/555) &(uu[i]<=545/555))nn[i]<-15
if((uu[i]>545/555) &(uu[i]<=552/555))nn[i]<-16
if((uu[i]>552/555) &(uu[i]<=553/555))nn[i]<-17
if(uu[i]>553/555)nn[i]<-18
y[i]<-rbinom(1,nn[i],ps[i])
data<-c(nsimul,dd[i],y[i],nn[i])
write(t(data), file = "d:\\bbsim\\m9r_2d5.txt",ncolumns =4,append = TRUE)
}
z<-list(dd=dd,y=y,nn=nn)

fit<-
optim(ss,bblik,bblik.g,method="L-BFGS-B",lower=rep(0,length(param)),hessian=
T,dd=z$dd,y=z$y,nn=z$nn)
if(fit$conv ==0){
var.bs<-solve(fit$hessian)
v.b1b2<- c(var.bs[2,2],var.bs[2,3],var.bs[3,3])
print(nsimul)
out<- c(nsimul,fit$par,v.b1b2)
nsimul<- nsimul+1
write(out, file ="d:\\bbsim\\m9pr_2d5.txt",ncolumns =11,append = TRUE)
}
}
print(fit$mess)
return(fit)

}

